@push('scripts')<script>document.querySelector('#id_room')?.addEventListener('change',async function(){const select=document.querySelector('#id_package');select.innerHTML='<option value="">Memuat paket...</option>';if(!this.value)return;const response=await fetch(`/studio/${this.value}`);select.innerHTML='<option value="">Pilih paket</option>';if(response.ok){const html=await response.text();const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('[data-package-id]').forEach(item=>{select.add(new Option(item.dataset.packageName,item.dataset.packageId));});}});</script>@endpush
